<script setup>import {onMounted,ref,nextTick} from 'vue';import api from '../../api';import {useAuthStore} from '../../stores/auth';import * as echarts from 'echarts';const auth=useAuthStore(),data=ref({summary:{},reservationStatus:[],deviceStatus:[]});const chart=ref();const names={PENDING:'待审核',APPROVED:'已通过',REJECTED:'已拒绝',CANCELLED:'已取消',COMPLETED:'已完成',NORMAL:'正常',FAULT:'故障',MAINTENANCE:'维修中'};const greeting=new Date().getHours()<12?'早上好':new Date().getHours()<18?'下午好':'晚上好';onMounted(async()=>{data.value=(await api.get('/dashboard')).data;await nextTick();const c=echarts.init(chart.value);c.setOption({color:['#168a92','#3f8fb2','#68b9b2','#f0aa68','#8a9da5'],tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',radius:['48%','72%'],center:['50%','44%'],itemStyle:{borderRadius:8,borderColor:'#fff',borderWidth:3},label:{formatter:'{b}\n{d}%'},data:data.value.reservationStatus.map(x=>({value:x.amount,name:names[x.name]||x.name}))}]});addEventListener('resize',()=>c.resize())});</script>
<template><div class="page"><div class="welcome"><div><span>工作台</span><h1>{{greeting}}，欢迎回来</h1><p>这里汇总了实验室预约和设备运行的最新情况。</p></div><div class="date"><Calendar/><b>{{new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric'})}}</b></div></div><div class="cards"><div class="metric"><span class="ico teal"><Calendar/></span><div><p>预约总数</p><b>{{data.summary.reservations||0}}</b><small>全部预约记录</small></div></div><div class="metric"><span class="ico blue"><Bell/></span><div><p>待审核申请</p><b>{{data.summary.pending||0}}</b><small>需要及时处理</small></div></div><div class="metric"><span class="ico cyan"><Monitor/></span><div><p>设备总数</p><b>{{data.summary.devices||0}}</b><small>已录入设备台账</small></div></div><div class="metric"><span class="ico orange"><Warning/></span><div><p>待处理工单</p><b>{{data.summary.repairs||0}}</b><small>{{data.summary.faults||0}}台故障设备</small></div></div></div><div class="grid"><section class="panel chart"><div class="section-head"><div><b>预约状态分布</b><span>当前全部预约的状态占比</span></div><el-tag type="success" effect="plain">实时数据</el-tag></div><div ref="chart" class="chart-box"></div></section><section class="panel quick"><div class="section-head"><div><b>快捷操作</b><span>常用功能入口</span></div></div><router-link to="/labs"><span><School/></span><div><b>查看实验室</b><p>查询位置、容量与开放时间</p></div><ArrowRight/></router-link><router-link v-if="auth.user?.role !== 'SYSTEM_ADMIN'" to="/reservations"><span><Calendar/></span><div><b>预约管理</b><p>提交申请或处理待审核预约</p></div><ArrowRight/></router-link><router-link to="/repairs"><span><Tools/></span><div><b>设备报修</b><p>上报故障并跟踪维修进度</p></div><ArrowRight/></router-link></section></div></div></template>
<style scoped>.welcome{padding:28px 30px;background:linear-gradient(105deg,#0f7480,#178f93 58%,#338bab);color:#fff;display:flex;justify-content:space-between;align-items:center;position:relative;overflow:hidden}.welcome:after{content:'';position:absolute;width:320px;height:320px;border-radius:50%;right:12%;top:-210px;border:50px solid #ffffff0d}.welcome span{font-size:12px;opacity:.8}.welcome h1{margin:8px 0;font-size:26px}.welcome p{margin:0;color:#d1eeee;font-size:13px}.date{display:flex;align-items:center;gap:9px;background:#ffffff18;border:1px solid #ffffff25;padding:12px 16px;border-radius:10px;z-index:1}.date svg{width:18px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:22px 0}.metric{background:#fff;border:1px solid var(--border);border-radius:13px;padding:20px;display:flex;gap:15px;box-shadow:0 5px 18px #1a718008}.metric .ico{width:46px;height:46px;border-radius:12px;display:grid;place-items:center}.ico svg{width:22px}.teal{background:#e7f7f5;color:#168a92}.blue{background:#eaf3fa;color:#3b83a8}.cyan{background:#e8f7fa;color:#278a9b}.orange{background:#fff3e6;color:#d98436}.metric p{margin:0;color:#71858c;font-size:13px}.metric b{display:block;font-size:27px;margin:5px 0}.metric small{color:#9babad}.grid{display:grid;grid-template-columns:2fr 1fr;gap:16px}.section-head{display:flex;justify-content:space-between;padding:20px 22px;border-bottom:1px solid #edf2f3}.section-head>div{display:flex;flex-direction:column;gap:5px}.section-head span{font-size:12px;color:#8da0a5}.chart-box{height:330px}.quick{padding-bottom:10px}.quick a{display:flex;align-items:center;gap:13px;margin:10px 14px;padding:14px;border-radius:10px;text-decoration:none;color:var(--ink);transition:.2s}.quick a:hover{background:#f1f9f9}.quick a>span{width:40px;height:40px;border-radius:10px;background:var(--primary-light);color:var(--primary);display:grid;place-items:center}.quick svg{width:17px}.quick a>div{flex:1}.quick a b{font-size:14px}.quick p{font-size:12px;color:#8a9ca1;margin:5px 0 0}@media(max-width:1000px){.cards{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:600px){.cards{grid-template-columns:1fr}.date{display:none}}</style>
